bounded_host_request.command:
set -eu
name=gace-createvdobot-videobot-poll-1
img=create-videobot:native-sticker-c8c50d4
target="$HOME/.local/share/gace-create-videobot/native-sticker-c8c50d420c0b9b5d447a1fc87ef3d9e1ec7aceed"
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo BOT_NOT_RUNNING; exit 81; }
test -f "$target/deploy/compose.videobot.poll.yaml" || { echo DEPLOY_SOURCE_NOT_FOUND; exit 82; }
docker image inspect "$img" >/dev/null || { echo VERIFIED_IMAGE_NOT_FOUND; exit 83; }
docker run --rm --network none --pull never --entrypoint grep "$img" -q 'ステッカー・絵文字' /opt/videobot/src/telegram/menuPanel.mjs || { echo VERIFIED_MENU_MISSING; exit 84; }
docker run --rm --network none --pull never --entrypoint grep "$img" -q 'there is no text in the message to edit' /opt/videobot/src/telegram/creatorScreenTransport.mjs || { echo VERIFIED_DM_FIX_MISSING; exit 85; }
token="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_telegram_token"}}{{.Source}}{{end}}{{end}}' "$name")"
dbpass="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_db_password"}}{{.Source}}{{end}}{{end}}' "$name")"
test -f "$token" && test -f "$dbpass" || { echo BOT_SECRET_MOUNT_MISSING; exit 86; }
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || { echo BOT_DB_AMBIGUOUS; exit 87; }
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
net="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$pg" | sed '/^$/d')"
test -n "$user" && test "$net" = deploy_default || { echo BOT_DB_NETWORK_INVALID; exit 88; }
pin="$HOME/.local/state/create-videobot/sticker-pin"
test -f "$pin/group2373696859_thread4640.json" || { echo BOT_EXISTING_PIN_MISSING; exit 89; }
export VIDEOBOT_TELEGRAM_TOKEN_SOURCE="$token" VIDEOBOT_DB_PASSWORD_SOURCE="$dbpass"
export VIDEOBOT_STICKER_PIN_STATE_SOURCE="$pin" GSERVER_POSTGRES_USER="$user" GSERVER_POSTGRES_NETWORK="$net"
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" config --quiet || { echo BOT_COMPOSE_INVALID; exit 90; }
test "$(docker ps --format '{{.Names}}' | grep -Ec 'createvdobot|create-videobot|videobot-poll' || true)" -eq 1 || { echo BOT_MULTIPLE_CONSUMERS; exit 91; }
armed=0
rollback(){
  docker image tag create-videobot:menu-before-fix create-videobot:local-poll || true
  docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" up -d --no-build --force-recreate videobot-poll >/dev/null 2>&1 || true
  echo BOT_MENU_ROLLBACK_ATTEMPTED
}
trap 'if test "$armed" = 1; then rollback; fi' EXIT
docker image tag create-videobot:local-poll create-videobot:menu-before-fix
armed=1
docker image tag "$img" create-videobot:local-poll
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" up -d --no-build --force-recreate videobot-poll >/dev/null 2>&1 || { echo BOT_RECREATE_FAILED; exit 92; }
sleep 10
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo BOT_NEW_NOT_RUNNING; exit 93; }
ready="$(docker logs --tail 1000 "$name" 2>&1 | grep -c '^CREATOR_DM_POLL_READY=PASS$' || true)"
gate="$(docker logs --tail 1000 "$name" 2>&1 | grep -c '^CREATOR_GATE_PUBLIC_RELEASE=CONNECTED$' || true)"
test "$ready" -ge 1 || { echo BOT_NEW_POLL_NOT_READY; exit 94; }
test "$gate" -ge 1 || { echo BOT_NEW_GATE_NOT_CONNECTED; exit 95; }
docker exec "$name" grep -q 'ステッカー・絵文字' /opt/videobot/src/telegram/menuPanel.mjs || { echo BOT_NEW_HOME_MENU_MISSING; exit 96; }
docker exec "$name" grep -q 'there is no text in the message to edit' /opt/videobot/src/telegram/creatorScreenTransport.mjs || { echo BOT_NEW_DM_FIX_MISSING; exit 97; }
test "$(docker ps --format '{{.Names}}' | grep -Ec 'createvdobot|create-videobot|videobot-poll' || true)" -eq 1 || { echo BOT_NEW_MULTIPLE_CONSUMERS; exit 98; }
armed=0
echo BOT_MENU_RESTORED_SOURCE_RUNTIME=PASS
echo BOT_DM_POLL_READY=PASS
echo BOT_GATE_CONNECTED=PASS
